import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.DC2M1AAK.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md"}'),s={name:"reference/changelog.md"};function n(i,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><ul><li><strong>site</strong>: <a href="https://marg-adk.github.io/marg" target="_blank" rel="noreferrer">https://marg-adk.github.io/marg</a> — VitePress on GitHub Pages, built from the repository&#39;s docs on every merge (<code>website/</code>, <code>npm run site:build</code>): a landing page, Get started · Build · Components · Run · Reference · Community, search, a comparison page, an FAQ. Pull requests build it, so a dead link fails the PR.</li><li><strong>docs</strong>: a review of adk.dev and what Marg takes from it (<code>docs/reviews/</code>), and ROADMAP &quot;0.3 — the surface&quot;: the site, the playground as the dev UI, a <code>marg</code> CLI, a skill for coding agents, provider pages, user simulation.</li><li><strong>deploy</strong>: the image ships <code>tsconfig.base.json</code> (without it tsx lost the path mappings and the gateway crashed at boot — the first Render deploy failed on this); CI now builds the image and probes its health, playground and widget (<code>image</code> job, required).</li><li><strong>docs</strong>: the launch post, <code>docs/posts/the-model-must-never-read-yes.md</code> (the long form, the Show HN comment, the r/LLMDevs post, the thread), linked from the README.</li><li><strong>docs</strong>: the README opens with <code>docs/images/playground.gif</code>, the six-turn journey recorded from the playground on the mock model (0.14 MB).</li><li><strong>playground</strong>: <code>render.yaml</code>, a Render Blueprint for the hosted playground (mock model, writes off, no login, rate limits on), deployed at <a href="https://marg-playground.onrender.com" target="_blank" rel="noreferrer">https://marg-playground.onrender.com</a> and linked from the README.</li><li><strong>core</strong>: the form-reply pair parser scans instead of matching a regex that backtracked polynomially on long runs of spaces in user text (CodeQL, high). The Docker healthcheck and the CI gate poll <code>/api/health</code>, the path the gateway serves.</li><li><strong>repository</strong>: the gate runs on Node 22 and 24 with <code>npm run lint</code> (ESLint, correctness rules only) first; CodeQL, a security workflow (dependency review, <code>npm audit</code>; GitHub secret scanning with push protection on the repository) and the OpenSSF Scorecard run on every PR or weekly; Dependabot keeps npm and Actions current in grouped weekly PRs; CODEOWNERS, issue templates (bug, feature, domain request), a pull-request template that asks for the gate output and a classification of every red, <code>RELEASING.md</code>, <code>.nvmrc</code>, <code>.editorconfig</code>, and badges in the README.</li><li><strong>packages</strong>: every package is publishable — a build per package (<code>tsc -p tsconfig.build.json</code> to <code>dist/</code>, ESM + <code>.d.ts</code>), <code>exports</code>, <code>types</code>, <code>files</code>, <code>publishConfig.access: public</code>; <code>@marg-adk/widget</code> is now a package (the file plus a manifest); <code>@marg-adk/gateway</code> ships a <code>marg-gateway</code> command that registers the tsx loader and runs the compiled server. The tsx development path through <code>tsconfig.json</code> paths is unchanged.</li><li><strong>create-marg-app</strong>: <code>npx create-marg-app my-agent</code> copies the templates, the example domain, the shared skills and the scaffolder into a fresh project depending on the published packages.</li><li><strong>core</strong>: when installed from npm the project root is the working directory (walking up to the nearest <code>package.json</code> or <code>.git</code>), so <code>.env</code>, <code>domains/</code>, <code>examples/</code> and <code>shared-skills/</code> are found in the user&#39;s project; <code>AGENT_REPO_ROOT</code> still overrides.</li><li><strong>gateway</strong>: the playground page and the widget are located relative to their packages, not the repository; <code>/api/skills</code> honours <code>AGENT_SHARED_SKILLS_DIR</code>.</li><li><strong>checks</strong>: <code>check:pack</code> (every package packs clean) and <code>check:create</code> (a project from local tarballs installs, boots and passes the example suite); a <code>packages</code> CI job runs both.</li><li><strong>release</strong>: a tag <code>v*</code> runs the gate and publishes every package with provenance (<code>NPM_TOKEN</code>).</li></ul><h2 id="_0-1-0-—-2026-10-13" tabindex="-1">0.1.0 — 2026-10-13 <a class="header-anchor" href="#_0-1-0-—-2026-10-13" aria-label="Permalink to &quot;0.1.0 — 2026-10-13&quot;">​</a></h2><p>First open-source release, extracted and generalised from a production agent.</p><ul><li><strong>core</strong>: the domain-agnostic runtime — prompt assembly from markdown skills (typed variants, capabilities, security preamble), the model chain (Anthropic, any OpenAI-compatible endpoint, a scripted mock) with failover, breaker, retries and per-endpoint configuration, MCP tools with reconnect and hidden <code>internal_*</code> tools, sessions with bounded memory and healed history windows, durable stores with fallback, two-stage tool-output trimming, <strong>runtime-owned steps</strong> (draw / read / settle / chain / late draw / redraw / review / carry / dependencies / reload redraw), whole-content readers, the create gate and attested-list guard, tolerant ui-block parsing and sanitising, OpenTelemetry seam, structured logs off the main thread.</li><li><strong>verdict</strong>: typed decisions (<code>choice</code> / <code>noul</code> / <code>score</code>) with rules, System One (Laya / any compatible server), LLM logprobs and mock backends; a cascade; calibration maths; a CLI, an MCP server and a System One-compatible HTTP server.</li><li><strong>gateway</strong>: HTTP + SSE; sessions with verified identity and owner checks; the agent-token exchange; rate limits with runtime-turn refunds; usage caps in plan tokens shown as percentages; media (upload ≠ attach); voice (Deepgram or any Whisper-compatible endpoint); nudges; health, metrics, HTTP tracing; a metering sink; graceful shutdown.</li><li><strong>evals</strong>: the scenario runner with sharding, reruns, flake classification and a gate report.</li><li><strong>widget</strong>: streaming, chips, multichips, lists, cards with sections, toggles, forms with echoes, tables, progress, media, bars; resume, nudges, voice, uploads; link scheme allowlist.</li><li><strong>example</strong>: support ticket intake, end to end offline with a scripted mock model; 7 scenarios.</li><li><strong>checks</strong>: <code>check:otel</code> (the telemetry seam against in-memory exporters and a stub log sink), <code>check:scaffold</code> (the templates produce a domain that compiles and passes its own suite), <code>check:e2e</code> (the real write path with writes on); the widget driven under a fake DOM in tests.</li><li><strong>observability</strong>: Docker Compose for OpenObserve (+ optional collector), generated dashboards and alerts (<code>o2:dashboards</code>), an idempotent <code>o2:bootstrap</code>.</li><li><strong>deploy</strong>: a non-root Dockerfile with a health check, Compose profiles (stores, observability, decisions with Ollama + laya, edge with Caddy), a production env example, DEPLOY.md; a CI workflow.</li><li><strong>docs</strong>: the pattern, the lessons, the playbook, the production checklist, the client protocol, decisions, observability, metering, security, the auth design, six ADRs, guides, templates.</li></ul><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/CHANGELOG.md">CHANGELOG.md</a> — edit it there; the site mirrors the repository.</small></p>',8)])])}const m=o(s,[["render",n]]);export{p as __pageData,m as default};
